options.styles:
& {
  --pv: #e8a400;
  --grid: #e0533c;
  --bat: #2bb673;
  --home: #3d8bfd;
  --goe: #9b6bff;
  --muted: rgba(128, 128, 128, 0.35);
}

/* The picture is drawn on a 440 x 400 grid; --u is one grid unit, so it
   scales with the panel and keeps its aspect ratio. */
& .dt-row {
  height: 100%;
  padding: 0;
  container-type: size;
}

& .stage {
  --u: calc(min(100cqw, 110cqh) / 440);
  position: relative;
  width: calc(var(--u) * 440);
  height: calc(var(--u) * 400);
  margin: 0 auto;
}

& .stage.stale {
  opacity: 0.4;
}

& .stage > div {
  position: absolute;
}

& .updated {
  left: 50%;
  top: 0;
  transform: translateX(-50%);
  font-size: calc(var(--u) * 12);
  opacity: 0.7;
}

& .tag {
  display: flex;
  flex-direction: column;
  align-items: center;
  line-height: 1.25;
  white-space: nowrap;
  transform: translateX(-50%);
}

& .name {
  font-size: calc(var(--u) * 12);
  opacity: 0.7;
}

& .value {
  font-size: calc(var(--u) * 16);
  font-weight: 600;
}

& .tag.pv { left: calc(var(--u) * 80); top: calc(var(--u) * 26); }
& .tag.grid { left: calc(var(--u) * 360); top: calc(var(--u) * 26); }
& .tag.bat { left: calc(var(--u) * 80); top: calc(var(--u) * 268); }
& .tag.home { left: calc(var(--u) * 360); top: calc(var(--u) * 268); }
& .tag.goe-left { left: calc(var(--u) * 186); top: calc(var(--u) * 306); align-items: flex-end; transform: translateX(-100%); }
& .tag.goe-right { left: calc(var(--u) * 254); top: calc(var(--u) * 306); align-items: flex-start; transform: none; }

& .node {
  width: calc(var(--u) * 52);
  height: calc(var(--u) * 52);
  margin: calc(var(--u) * -26) 0 0 calc(var(--u) * -26);
  box-sizing: border-box;
  border: calc(var(--u) * 2.5) solid;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: calc(var(--u) * 22);
}

& .node.pv { left: calc(var(--u) * 80); top: calc(var(--u) * 95); border-color: var(--pv); }
& .node.grid { left: calc(var(--u) * 360); top: calc(var(--u) * 95); border-color: var(--grid); }
& .node.bat { left: calc(var(--u) * 80); top: calc(var(--u) * 235); border-color: var(--bat); }
& .node.home { left: calc(var(--u) * 360); top: calc(var(--u) * 235); border-color: var(--home); }
& .node.goe { left: calc(var(--u) * 220); top: calc(var(--u) * 325); border-color: var(--goe); }

/* Nodes without power flow are grey, like their lines. */
& .node.off {
  border-color: var(--muted);
  filter: grayscale(1);
  opacity: 0.6;
}

& .hub {
  left: calc(var(--u) * 213);
  top: calc(var(--u) * 168);
  width: calc(var(--u) * 14);
  height: calc(var(--u) * 14);
  border-radius: 50%;
  background: currentColor;
  opacity: 0.5;
}

/* A line starts at (left, top) and is rotated around its left end. Moving
   dots show the direction: fwd runs from the start to the end, rev back. */
& .line {
  transform-origin: 0 50%;
  border-radius: 999px;
  --c: var(--muted);
  background: var(--muted);
}

& .line.on {
  background:
    radial-gradient(circle, var(--c) 40%, transparent 45%) 0 50% / calc(var(--u) * 10) 100% repeat-x,
    linear-gradient(color-mix(in srgb, var(--c) 35%, transparent), color-mix(in srgb, var(--c) 35%, transparent));
  animation: energy-flow 0.8s linear infinite;
}

& .line.rev {
  animation-direction: reverse;
}

& .line.pv.on { --c: var(--pv); }
& .line.grid.on { --c: var(--grid); }
& .line.bat.on { --c: var(--bat); }
& .line.home.on { --c: var(--home); }
& .line.goe.on { --c: var(--goe); }

& .line.off, & .line.w1 { height: calc(var(--u) * 2.5); margin-top: calc(var(--u) * -1.25); }
& .line.on.w2 { height: calc(var(--u) * 3.5); margin-top: calc(var(--u) * -1.75); }
& .line.on.w3 { height: calc(var(--u) * 5); margin-top: calc(var(--u) * -2.5); }
& .line.on.w4 { height: calc(var(--u) * 6.5); margin-top: calc(var(--u) * -3.25); }
& .line.on.w5 { height: calc(var(--u) * 8); margin-top: calc(var(--u) * -4); }

@keyframes energy-flow {
  from { background-position: 0 50%, 0 0; }
  to { background-position: calc(var(--u) * 10) 50%, 0 0; }
}

& .split {
  left: calc(var(--u) * 130);
  top: calc(var(--u) * 362);
  width: calc(var(--u) * 180);
}

& .split.off {
  opacity: 0.3;
}

& .bar {
  display: flex;
  height: calc(var(--u) * 7);
  border-radius: calc(var(--u) * 3.5);
  overflow: hidden;
  background: var(--muted);
}

& .seg.pv { background: var(--pv); }
& .seg.bat { background: var(--bat); }
& .seg.grid { background: var(--grid); }

& .legend {
  margin-top: calc(var(--u) * 4);
  text-align: center;
  white-space: nowrap;
  font-size: calc(var(--u) * 12);
  opacity: 0.7;
}

@media (prefers-reduced-motion: reduce) {
  & .line.on { animation: none; }
}
& .line.pv { left: calc(var(--u) * 104.3); top: calc(var(--u) * 108.9); width: calc(var(--u) * 125.3); transform: rotate(29.7deg); }
& .line.grid { left: calc(var(--u) * 335.7); top: calc(var(--u) * 108.9); width: calc(var(--u) * 125.3); transform: rotate(150.3deg); }
& .line.bat { left: calc(var(--u) * 105.7); top: calc(var(--u) * 224.0); width: calc(var(--u) * 116.3); transform: rotate(-23.2deg); }
& .line.home { left: calc(var(--u) * 227.4); top: calc(var(--u) * 178.2); width: calc(var(--u) * 116.3); transform: rotate(23.2deg); }
& .line.goe { left: calc(var(--u) * 220); top: calc(var(--u) * 183); width: calc(var(--u) * 114.0); transform: rotate(90.0deg); }
